function getScriptedCameras(): ScriptedCamera[] {
  return [
    {
      cameraId: "cam-4",
      events: [
        { ts: hourToTs(0, 0), status: "ok" },
        { ts: hourToTs(11, 5), status: "degraded" },
        { ts: hourToTs(13, 30), status: "offline" },
        { ts: hourToTs(19, 0), status: "ok" },
      ],
    },
  ];
}

function getCameraStatusAt(
  cameraId: string,
  ts: number,
  scripted: ScriptedCamera[]
): "ok" | "degraded" | "offline" {
  const script = scripted.find((s) => s.cameraId === cameraId);
  if (!script) return "ok";
  let status: "ok" | "degraded" | "offline" = "ok";
  for (const ev of script.events) {
    if (ev.ts <= ts) status = ev.status;
  }
  return status;
}

function generateSignals(
  zones: ShelfZone[],
  seed: number
): { signals: ShelfGapSignal[]; heartbeats: CameraHeartbeat[] } {
  const rng = createRng(seed);
  const signals: ShelfGapSignal[] = [];
  const heartbeats: CameraHeartbeat[] = [];
  const scriptedGaps = getScriptedGaps();
  const scriptedCameras = getScriptedCameras();

  const dayStart = getDayStartTs();
  const dayEnd = getDayEndTs();
  const dropRate = SIGNAL_DROP_RATE + rng.float(-0.03, 0.04);

  const cameraIds = [
    "cam-1",
    "cam-2",
    "cam-3",
    "cam-4",
    "cam-5",
    "cam-6",
    "cam-7",
    "cam-8",
  ];

  // Generate check times with jitter
  const checkTimes: number[] = [];
  let t = dayStart;
  while (t < dayEnd) {
    const jitter = rng.int(-45, 45) * 1000;
    checkTimes.push(t + jitter);
    t += CHECK_INTERVAL_MS;
  }

  for (const camId of cameraIds) {
    for (const checkTs of checkTimes) {
      if (checkTs < dayStart || checkTs >= dayEnd) continue;

      const status = getCameraStatusAt(camId, checkTs, scriptedCameras);
      heartbeats.push({ cameraId: camId, ts: checkTs, status });

      const camZones = zones.filter((z) => z.cameraId === camId && z.covered);

      for (const zone of camZones) {
        // Random signal drop
        if (rng.chance(dropRate)) continue;
        if (status === "offline") continue;

        for (const sku of zone.skus) {
          const scripted = scriptedGaps.find(
            (g) =>
              g.zoneId === zone.id &&
              g.skuCode === sku.code &&
              checkTs >= g.startTs &&
              checkTs < g.endTs
          );

          let gapRatio: number;
          if (scripted) {
            gapRatio = scripted.gapRatio + rng.float(-0.05, 0.05);
          } else {
            gapRatio = rng.chance(0.08) ? rng.float(0.65, 0.9) : rng.float(0, 0.3);
          }

          let confidence: number;
          if (LOW_CONFIDENCE_ZONES.includes(zone.id)) {
            confidence = Math.min(0.55, rng.gaussian(0.45, 0.08));
          } else {
            confidence = Math.max(0.3, Math.min(0.95, rng.gaussian(0.72, 0.15)));
          }

          if (status === "degraded") {
            confidence *= 0.85;
          }

          signals.push({
            zoneId: zone.id,
            ts: checkTs,
            gapRatio: Math.max(0, Math.min(1, gapRatio)),
            confidence: Math.max(0.2, Math.min(1, confidence)),
          });
        }
      }
    }
  }

  return { signals, heartbeats };
}

function applyScriptedSales(inventory: InventoryRow[]): InventoryRow[] {
  const sales = getScriptedSales();
  const inv = inventory.map((r) => ({ ...r }));

  for (const sale of sales) {
    const row = inv.find(
      (r) => r.zoneId === sale.zoneId && r.skuCode === sale.skuCode
    );
    if (row) {
      row.lastSaleTs = sale.ts;
      if (row.systemStock > 0) {
        row.systemStock = Math.max(0, row.systemStock - 1);
      }
    }
  }

  return inv;
}

export function generateStoreData(seed: number): StoreData {
  const zones = buildZones();
  const inventory = applyScriptedSales(buildInventory(zones));
  const { signals, heartbeats } = generateSignals(zones, seed);

  return {
    zones,
    signals,
    heartbeats,
    staffEvents: [],
    inventory,
    lowConfidenceZones: LOW_CONFIDENCE_ZONES,
  };
}

export function getCameraZones(
  zones: ShelfZone[],
  cameraId: string
): ShelfZone[] {
  return zones.filter((z) => z.cameraId === cameraId);
}

export function getUncoveredZones(zones: ShelfZone[]): ShelfZone[] {
  return zones.filter((z) => !z.covered);
}

export function getSku(
  zones: ShelfZone[],
  zoneId: string,
  skuCode: string
) {
  const zone = zones.find((z) => z.id === zoneId);
  return zone?.skus.find((s) => s.code === skuCode);
}

export function getZone(zones: ShelfZone[], zoneId: string) {
  return zones.find((z) => z.id === zoneId);
}

export function getInventoryRow(
  inventory: InventoryRow[],
  zoneId: string,
  skuCode: string
): InventoryRow | undefined {
  return inventory.find(
    (r) => r.zoneId === zoneId && r.skuCode === skuCode
  );
}

export function getCameraStatusAtTs(
  heartbeats: CameraHeartbeat[],
  cameraId: string,
  ts: number
): "ok" | "degraded" | "offline" {
  const relevant = heartbeats
    .filter((h) => h.cameraId === cameraId && h.ts <= ts)
    .sort((a, b) => b.ts - a.ts);
  return relevant[0]?.status ?? "ok";
}

export function getLastHeartbeat(
  heartbeats: CameraHeartbeat[],
  cameraId: string,
  ts: number
): CameraHeartbeat | undefined {
  return heartbeats
    .filter((h) => h.cameraId === cameraId && h.ts <= ts)
    .sort((a, b) => b.ts - a.ts)[0];
}

import type {
  ShelfZone,
  ShelfGapSignal,
  CameraHeartbeat,
  StaffPresent,
  InventoryRow,
  Task,
  TaskKind,
  ConfidenceLabel,
  StoreData,
} from "@/types";
import { isReplenishmentWindow } from "./time";
import { getSku, getZone, getInventoryRow, getCameraStatusAtTs } from "./generator";

const WINDOW_MS = 15 * 60 * 1000;
const GAP_THRESHOLD = 0.6;
const MIN_SIGHTINGS = 3;
const SIGHTING_WINDOW = 5;
const VALUE_FLOOR = 40;
const STAFF_TTL_MS = 60 * 1000;
const REVERSE_PHANTOM_NO_GAP_MS = 2 * 60 * 60 * 1000;
const REVERSE_PHANTOM_SALE_MS = 2 * 60 * 60 * 1000;
const FACING_SALE_MS = 30 * 60 * 1000;

export function getConfidenceLabel(
  confidence: number,
  mode: "observed" | "predicted"
): ConfidenceLabel {
  if (mode === "predicted" || confidence < 0.5) return "Predicted";
  if (confidence > 0.75) return "Confirmed";
  return "Likely";
}

function cameraHealthMultiplier(status: string): number {
  if (status === "ok") return 1.0;
  if (status === "degraded") return 0.7;
  return 0.5;
}

function getSignalsInWindow(
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number
): ShelfGapSignal[] {
  const windowStart = currentTs - WINDOW_MS;
  return signals
    .filter((s) => s.zoneId === zoneId && s.ts >= windowStart && s.ts <= currentTs)
    .sort((a, b) => a.ts - b.ts);
}

function getRecentChecks(
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number
): ShelfGapSignal[] {
  const all = signals
    .filter((s) => s.zoneId === zoneId && s.ts <= currentTs)
    .sort((a, b) => b.ts - a.ts);
  return all.slice(0, SIGHTING_WINDOW);
}

export function countSightings(
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number
): { seen: number; checks: number } {
  const recent = getRecentChecks(signals, zoneId, currentTs);
  const seen = recent.filter((s) => s.gapRatio > GAP_THRESHOLD).length;
  return { seen, checks: recent.length };
}

function hasSustainedGap(
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number
): { sustained: boolean; sightings: { seen: number; checks: number } } {
  const sightings = countSightings(signals, zoneId, currentTs);
  const sustained =
    sightings.checks >= SIGHTING_WINDOW &&
    sightings.seen >= MIN_SIGHTINGS;
  return { sustained, sightings };
}

function hasNoGapForDuration(
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number,
  durationMs: number
): boolean {
  const windowStart = currentTs - durationMs;
  const inWindow = signals.filter(
    (s) => s.zoneId === zoneId && s.ts >= windowStart && s.ts <= currentTs
  );
  if (inWindow.length === 0) return true;
  return inWindow.every((s) => s.gapRatio <= GAP_THRESHOLD);
}

function hasRecentSale(
  inv: InventoryRow | undefined,
  currentTs: number,
  windowMs: number
): boolean {
  if (!inv?.lastSaleTs) return false;
  return currentTs - inv.lastSaleTs <= windowMs;
}

function isStaffPresent(
  staffEvents: StaffPresent[],
  zoneId: string,
  currentTs: number
): boolean {
  return staffEvents.some(
    (e) => e.zoneId === zoneId && currentTs - e.ts < STAFF_TTL_MS
  );
}

function classifyKind(
  sustained: boolean,
  systemStock: number,
  inv: InventoryRow | undefined,
  signals: ShelfGapSignal[],
  zoneId: string,
  currentTs: number
): TaskKind | null {
  if (!sustained) {
    // reverse_phantom
    if (
      systemStock === 0 &&
      hasNoGapForDuration(signals, zoneId, currentTs, REVERSE_PHANTOM_NO_GAP_MS) &&
      hasRecentSale(inv, currentTs, REVERSE_PHANTOM_SALE_MS)
    ) {
      return "reverse_phantom";
    }
    return null;
  }

  if (systemStock === 0) return "true_oos";

  if (hasRecentSale(inv, currentTs, FACING_SALE_MS)) {
    return "facing";
  }

  return "phantom_suspected";
}

function computeValueAtRisk(
  hourlyVelocity: number,
  mrp: number
): number {
  return hourlyVelocity * mrp;
}

function computeTaskConfidence(
  windowSignals: ShelfGapSignal[],
  cameraStatus: string,
  mode: "observed" | "predicted"
): number {
  if (windowSignals.length === 0) return mode === "predicted" ? 0.4 : 0.3;
  const meanConf =
    windowSignals.reduce((s, sig) => s + sig.confidence, 0) /
    windowSignals.length;
  let conf = meanConf * cameraHealthMultiplier(cameraStatus);
  if (mode === "predicted") conf = Math.min(conf, 0.5);
  return conf;
}

function buildPredictedSignals(
  inv: InventoryRow,
  zoneId: string,
  currentTs: number,
  lastSignalTs: number
): ShelfGapSignal[] {
  if (!inv.hourlyVelocity || inv.systemStock <= 0) return [];
  const hoursSince = (currentTs - lastSignalTs) / (60 * 60 * 1000);
  const estimatedRemaining = inv.systemStock - inv.hourlyVelocity * hoursSince;
  if (estimatedRemaining > inv.systemStock * 0.3) return [];

  const gapRatio = Math.min(0.9, 1 - estimatedRemaining / (inv.systemStock || 1));
  return [
    {
      zoneId,
      ts: currentTs,
      gapRatio: Math.max(0.65, gapRatio),
      confidence: 0.4,
    },
  ];
}

export interface ClassifyInput {
  storeData: StoreData;
  currentTs: number;
  existingTasks: Task[];
}

export function classifyTasks(input: ClassifyInput): Task[] {
  const { storeData, currentTs, existingTasks } = input;
  const { zones, signals, heartbeats, staffEvents, inventory } = storeData;

  if (isReplenishmentWindow(currentTs)) {
    return existingTasks.filter((t) => t.state === "open");
  }

  const openTasks = existingTasks.filter((t) => t.state === "open");
  const closedTasks = existingTasks.filter((t) => t.state !== "open");
  const updatedOpen: Task[] = [...openTasks];

  const candidates: {
    zoneId: string;
    skuCode: string;
    kind: TaskKind;
    valueAtRisk: number;
    confidence: number;
    mode: "observed" | "predicted";
    sightings: { seen: number; checks: number };
    evidence: Task["evidence"];
  }[] = [];

  for (const zone of zones) {
    if (!zone.covered) continue;
    if (isStaffPresent(staffEvents, zone.id, currentTs)) continue;

    const cameraStatus = getCameraStatusAtTs(
      heartbeats,
      zone.cameraId,
      currentTs
    );
    const isOffline = cameraStatus === "offline";

    for (const sku of zone.skus) {
      const inv = getInventoryRow(inventory, zone.id, sku.code);
      if (!inv) continue;

      const existing = updatedOpen.find(
        (t) => t.zoneId === zone.id && t.skuCode === sku.code
      );

      let zoneSignals = getSignalsInWindow(signals, zone.id, currentTs);
      let mode: "observed" | "predicted" = "observed";

      if (isOffline) {
        mode = "predicted";
        const lastReal = signals
          .filter((s) => s.zoneId === zone.id && s.ts <= currentTs)
          .sort((a, b) => b.ts - a.ts)[0];
        const predicted = buildPredictedSignals(
          inv,
          zone.id,
          currentTs,
          lastReal?.ts ?? currentTs - WINDOW_MS
        );
        if (predicted.length > 0) {
          zoneSignals = predicted;
        }
      }

      const { sustained, sightings } = hasSustainedGap(
        isOffline ? zoneSignals : signals,
        zone.id,
        currentTs
      );

      const kind = classifyKind(
        sustained || (isOffline && zoneSignals.some((s) => s.gapRatio > GAP_THRESHOLD)),
        inv.systemStock,
        inv,
        signals,
        zone.id,
        currentTs
      );

      if (!kind) {
        if (existing) {
          // keep existing open task
        }
        continue;
      }

      const valueAtRisk = computeValueAtRisk(inv.hourlyVelocity, sku.mrp);
      if (valueAtRisk < VALUE_FLOOR && !existing) continue;

      const confidence = computeTaskConfidence(
        zoneSignals,
        cameraStatus,
        mode
      );

      const evidence: Task["evidence"] = {
        signals: zoneSignals,
        cameraStatus,
        systemStock: inv.systemStock,
        lastSaleTs: inv.lastSaleTs,
      };

      if (existing) {
        const idx = updatedOpen.indexOf(existing);
        updatedOpen[idx] = {
          ...existing,
          kind,
          valueAtRiskPerHour: valueAtRisk,
          confidence,
          mode,
          sightings,
          evidence,
        };
      } else {
        candidates.push({
          zoneId: zone.id,
          skuCode: sku.code,
          kind,
          valueAtRisk,
          confidence,
          mode,
          sightings,
          evidence,
        });
      }
    }
  }

  for (const c of candidates) {
    const id = `task-${c.zoneId}-${c.skuCode}-${currentTs}`;
    updatedOpen.push({
      id,
      zoneId: c.zoneId,
      skuCode: c.skuCode,
      kind: c.kind,
      valueAtRiskPerHour: c.valueAtRisk,
      confidence: c.confidence,
      mode: c.mode,
      openedTs: currentTs,
      sightings: c.sightings,
      evidence: c.evidence,
      state: "open",
    });
  }

  return [...closedTasks, ...updatedOpen];
}

export function collapseFacingTasks(tasks: Task[]): Task[] {
  const open = tasks.filter((t) => t.state === "open");
  const closed = tasks.filter((t) => t.state !== "open");

  const facingByAisle = new Map<string, Task[]>();
  const nonFacing: Task[] = [];

  for (const t of open) {
    if (t.kind === "facing") {
      const zone = t.zoneId;
      const aisle = zone.split("-")[0];
      const key = `Aisle ${aisle.replace("A", "")}`;
      const list = facingByAisle.get(key) ?? [];
      list.push(t);
      facingByAisle.set(key, list);
    } else {
      nonFacing.push(t);
    }
  }

  const collapsedFacing: Task[] = [];
  for (const [aisle, facingTasks] of facingByAisle) {
    if (facingTasks.length === 0) continue;
    const totalValue = facingTasks.reduce(
      (s, t) => s + t.valueAtRiskPerHour,
      0
    );
    const lowest = facingTasks.reduce((a, b) =>
      a.confidence < b.confidence ? a : b
    );
    collapsedFacing.push({
      ...lowest,
      id: `facing-${aisle}`,
      valueAtRiskPerHour: totalValue,
      kind: "facing",
    });
  }

  return [
    ...closed,
    ...nonFacing,
    ...collapsedFacing,
  ];
}

export function getOpenTasks(tasks: Task[], currentTs: number): Task[] {
  return tasks
    .filter((t) => t.state === "open")
    .sort((a, b) => b.valueAtRiskPerHour - a.valueAtRiskPerHour);
}

export function getTaskAction(kind: TaskKind): string {
  switch (kind) {
    case "phantom_suspected":
      return "Check backroom";
    case "true_oos":
      return "Order or substitute";
    case "reverse_phantom":
      return "Recount";
    case "facing":
      return "Tidy aisle";
  }
}

export function getDisagreementSentence(
  task: Task,
  zones: ShelfZone[]
): string {
  const zone = getZone(zones, task.zoneId);
  const sku = getSku(zones, task.zoneId, task.skuCode);
  const { seen, checks } = task.sightings;
  const stock = task.evidence.systemStock;

  if (task.kind === "reverse_phantom") {
    return `System shows 0 units but sales are still happening. Shelf looks stocked.`;
  }

  if (task.kind === "facing") {
    return `Shelf looks thin in ${zone?.section ?? "this section"} but sales are still ticking.`;
  }

  if (task.kind === "true_oos") {
    return `System shows 0 units. Shelf has read empty in ${seen} of the last ${checks} checks.`;
  }

  return `System shows ${stock} units. Shelf has read empty in ${seen} of the last ${checks} checks.`;
}

export function getClassificationExplanation(
  task: Task,
  zones: ShelfZone[]
): string {
  const sku = getSku(zones, task.zoneId, task.skuCode);
  const stock = task.evidence.systemStock;
  const { seen, checks } = task.sightings;

  switch (task.kind) {
    case "phantom_suspected":
      return `Shelf read empty in ${seen} of ${checks} recent checks, but the system still shows ${stock} units of ${sku?.name ?? "this item"}. Stock is likely in the backroom.`;
    case "true_oos":
      return `Shelf empty in ${seen} of ${checks} checks and system stock is zero. Nothing on the floor can fix this — order or substitute.`;
    case "reverse_phantom":
      return `No gap detected for 2 hours, but the system shows zero stock while sales continue. The item is probably on the shelf — recount needed.`;
    case "facing":
      return `Shelf looks thin but sales are still happening in the last 30 minutes. This is a facing issue, not a stock-out.`;
  }
}

export function formatRupee(amount: number): string {
  return `₹${Math.round(amount).toLocaleString("en-IN")}`;
}

"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useMemo,
  useEffect,
  type ReactNode,
} from "react";
import { generateStoreData } from "@/lib/generator";
import {
  classifyTasks,
  collapseFacingTasks,
  getOpenTasks,
} from "@/lib/classification";
import { parseSeedFromUrl } from "@/lib/seed";
import {
  getDefaultStartTs,
  getDayStartTs,
  getDayEndTs,
  isTradingHours,
} from "@/lib/time";
import type { Task, StoreData, ToastMessage } from "@/types";

interface SimulationContextValue {
  currentTs: number;
  isPlaying: boolean;
  seed: number;
  storeData: StoreData;
  tasks: Task[];
  openTasks: Task[];
  totalAtRisk: number;
  play: () => void;
  pause: () => void;
  setTime: (ts: number) => void;
  resolveRestocked: (taskId: string) => void;
  resolveNotFound: (taskId: string) => void;
  dismissWrongCall: (taskId: string) => void;
  toasts: ToastMessage[];
  dismissToast: (id: string) => void;
  adjustStock: (zoneId: string, skuCode: string, newStock: number) => void;
}

const SimulationContext = createContext<SimulationContextValue | null>(null);

const PLAY_SPEED = 60; // 1 real second = 1 sim minute

export function SimulationProvider({ children }: { children: ReactNode }) {
  const [seed] = useState(() => parseSeedFromUrl());
  const [storeData, setStoreData] = useState<StoreData>(() =>
    generateStoreData(seed)
  );
  const [currentTs, setCurrentTs] = useState(getDefaultStartTs);
  const [isPlaying, setIsPlaying] = useState(false);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);

  const classified = useMemo(() => {
    const classified = classifyTasks({
      storeData,
      currentTs,
      existingTasks: tasks,
    });
    return collapseFacingTasks(classified);
  }, [storeData, currentTs, tasks]);

  const openTasks = useMemo(
    () => getOpenTasks(classified, currentTs),
    [classified, currentTs]
  );

  const totalAtRisk = useMemo(
    () => openTasks.reduce((s, t) => s + t.valueAtRiskPerHour, 0),
    [openTasks]
  );

  // Re-classify when time changes (but don't reset manual task state)
  useEffect(() => {
    const classified = classifyTasks({
      storeData,
      currentTs,
      existingTasks: tasks,
    });
    const collapsed = collapseFacingTasks(classified);
    const openIds = new Set(
      tasks.filter((t) => t.state !== "open").map((t) => t.id)
    );
    const merged = collapsed.map((t) => {
      const manual = tasks.find(
        (mt) =>
          mt.id === t.id ||
          (mt.zoneId === t.zoneId &&
            mt.skuCode === t.skuCode &&
            mt.state !== "open")
      );
      if (manual && manual.state !== "open") return manual;
      return t;
    });
    const existingOpen = tasks.filter((t) => t.state === "open");
    const newOpens = collapsed.filter(
      (t) =>
        t.state === "open" &&
        !existingOpen.some(
          (e) => e.zoneId === t.zoneId && e.skuCode === t.skuCode
        ) &&
        !openIds.has(t.id)
    );
    if (newOpens.length > 0 || merged.length !== tasks.length) {
      setTasks(merged);
    }
  }, [currentTs, storeData]);

  useEffect(() => {
    if (!isPlaying) return;
    const interval = setInterval(() => {
      setCurrentTs((prev) => {
        const next = prev + PLAY_SPEED * 1000;
        const dayEnd = getDayEndTs();
        if (next >= dayEnd) {
          setIsPlaying(false);
          return dayEnd;
        }
        return next;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [isPlaying]);

  const addToast = useCallback((text: string) => {
    const id = `toast-${Date.now()}`;
    setToasts((prev) => [...prev, { id, text }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  const play = useCallback(() => setIsPlaying(true), []);
  const pause = useCallback(() => setIsPlaying(false), []);

  const setTime = useCallback((ts: number) => {
    const dayStart = getDayStartTs();
    const dayEnd = getDayEndTs();
    setCurrentTs(Math.max(dayStart, Math.min(dayEnd, ts)));
  }, []);

  const resolveRestocked = useCallback(
    (taskId: string) => {
      setTasks((prev) =>
        prev.map((t) =>
          t.id === taskId ? { ...t, state: "resolved_restocked" } : t
        )
      );
    },
    []
  );

  const resolveNotFound = useCallback(
    (taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task) return;

      setStoreData((prev) => ({
        ...prev,
        inventory: prev.inventory.map((r) =>
          r.zoneId === task.zoneId && r.skuCode === task.skuCode
            ? { ...r, systemStock: 0 }
            : r
        ),
      }));

      setTasks((prev) =>
        prev.map((t) =>
          t.id === taskId ? { ...t, state: "resolved_not_found" } : t
        )
      );

      const value = task.valueAtRiskPerHour;
      addToast(
        `Stock set to 0. ₹${Math.round(value).toLocaleString("en-IN")}/hr at risk cleared. Store pickup will stop promising this item.`
      );
    },
    [tasks, addToast]
  );

  const dismissWrongCall = useCallback(
    (taskId: string) => {
      setTasks((prev) =>
        prev.map((t) =>
          t.id === taskId ? { ...t, state: "dismissed_wrong_call" } : t
        )
      );
      addToast("Dismissed. This feedback trains the detector for next time.");
    },
    [addToast]
  );

  const adjustStock = useCallback(
    (zoneId: string, skuCode: string, newStock: number) => {
      setStoreData((prev) => ({
        ...prev,
        inventory: prev.inventory.map((r) =>
          r.zoneId === zoneId && r.skuCode === skuCode
            ? { ...r, systemStock: newStock }
            : r
        ),
      }));
    },
    []
  );

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const value: SimulationContextValue = {
    currentTs,
    isPlaying,
    seed,
    storeData,
    tasks: classified,
    openTasks,
    totalAtRisk,
    play,
    pause,
    setTime,
    resolveRestocked,
    resolveNotFound,
    dismissWrongCall,
    toasts,
    dismissToast,
    adjustStock,
  };

  return (
    <SimulationContext.Provider value={value}>
      {children}
    </SimulationContext.Provider>
  );
}

export function useSimulation() {
  const ctx = useContext(SimulationContext);
  if (!ctx) throw new Error("useSimulation must be used within SimulationProvider");
  return ctx;
}

"use client";

import { useSimulation } from "@/hooks/useSimulation";
import { tsToClock, getDayStartTs, getDayEndTs } from "@/lib/time";

export function ClockScrubber() {
  const { currentTs, isPlaying, play, pause, setTime, seed } = useSimulation();
  const dayStart = getDayStartTs();
  const dayEnd = getDayEndTs();
  const progress = ((currentTs - dayStart) / (dayEnd - dayStart)) * 100;

  return (
    <div className="sticky top-0 z-30 bg-white border-b border-neutral-200 px-4 py-3">
      <div className="flex items-center justify-between mb-2">
        <span className="text-2xl font-medium tabular-nums tracking-tight">
          {tsToClock(currentTs)}
        </span>
        <div className="flex items-center gap-2">
          <span className="text-xs text-neutral-400">seed {seed}</span>
          <button
            onClick={isPlaying ? pause : play}
            className="px-3 py-1.5 text-sm font-medium bg-neutral-900 text-white rounded"
            aria-label={isPlaying ? "Pause" : "Play"}
          >
            {isPlaying ? "Pause" : "Play"}
          </button>
        </div>
      </div>
      <input
        type="range"
        min={dayStart}
        max={dayEnd}
        value={currentTs}
        onChange={(e) => setTime(Number(e.target.value))}
        className="w-full h-1.5 appearance-none bg-neutral-200 rounded-full cursor-pointer
          [&::-webkit-slider-thumb]:appearance-none
          [&::-webkit-slider-thumb]:w-4
          [&::-webkit-slider-thumb]:h-4
          [&::-webkit-slider-thumb]:rounded-full
          [&::-webkit-slider-thumb]:bg-neutral-900"
        aria-label="Time scrubber"
      />
      <div className="flex justify-between text-xs text-neutral-400 mt-1">
        <span>06:00</span>
        <span>22:00</span>
      </div>
      <div
        className="absolute bottom-0 left-0 h-0.5 bg-neutral-900 transition-[width] duration-300 motion-reduce:transition-none"
        style={{ width: `${progress}%` }}
        aria-hidden
      />
    </div>
  );
}

"use client";

import { useSimulation } from "@/hooks/useSimulation";

export function ToastContainer() {
  const { toasts, dismissToast } = useSimulation();

  if (toasts.length === 0) return null;

  return (
    <div className="fixed bottom-20 left-4 right-4 z-50 flex flex-col gap-2 pointer-events-none">
      {toasts.map((toast) => (
        <div
          key={toast.id}
          className="bg-neutral-900 text-white text-sm px-4 py-3 rounded shadow-lg pointer-events-auto animate-slide-up motion-reduce:animate-none"
          onClick={() => dismissToast(toast.id)}
          role="status"
        >
          {toast.text}
        </div>
      ))}
    </div>
  );
}

"use client";

import { useState } from "react";
import type { Task } from "@/types";
import { getSku, getZone } from "@/lib/generator";
import { formatRupee } from "@/lib/classification";
import { useSimulation } from "@/hooks/useSimulation";

interface Props {
  task: Task;
  onClose: () => void;
}

export function NotInBackroomSheet({ task, onClose }: Props) {
  const { storeData, resolveNotFound } = useSimulation();
  const [confirmed, setConfirmed] = useState(false);
  const zone = getZone(storeData.zones, task.zoneId);
  const sku = getSku(storeData.zones, task.zoneId, task.skuCode);

  if (confirmed) {
    return (
      <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/40">
        <div className="bg-white w-full max-w-lg rounded-t-2xl p-6 pb-8">
          <p className="text-lg font-medium mb-2">Stock updated</p>
          <p className="text-neutral-600 mb-6">
