"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useMemo,
  useEffect,
  type ReactNode,
} from "react";
import { generateStoreData } from "@/lib/generator";
import {
  classifyTasks,
  collapseFacingTasks,
  getOpenTasks,
} from "@/lib/classification";
import { parseSeedFromUrl } from "@/lib/seed";
import { getDefaultStartTs, getDayEndTs } from "@/lib/time";
import type { Task, StoreData, ToastMessage } from "@/types";

type TaskOverride = {
  state: Task["state"];
  resolvedTs: number;
};

interface SimulationContextValue {
  currentTs: number;
  isPlaying: boolean;
  seed: number;
  storeData: StoreData;
  tasks: Task[];
  openTasks: Task[];
  totalAtRisk: number;
  play: () => void;
  pause: () => void;
  setTime: (ts: number) => void;
  resolveRestocked: (taskId: string) => void;
  resolveNotFound: (taskId: string) => void;
  dismissWrongCall: (taskId: string) => void;
  toasts: ToastMessage[];
  dismissToast: (id: string) => void;
  getTaskById: (id: string) => Task | undefined;
}

const SimulationContext = createContext<SimulationContextValue | null>(null);

const PLAY_SPEED = 60;

function taskKey(zoneId: string, skuCode: string) {
  return `${zoneId}::${skuCode}`;
}

export function SimulationProvider({ children }: { children: ReactNode }) {
  const [seed] = useState(() => parseSeedFromUrl());
  const [storeData, setStoreData] = useState<StoreData>(() =>
    generateStoreData(seed)
  );
  const [currentTs, setCurrentTs] = useState(getDefaultStartTs);
  const [isPlaying, setIsPlaying] = useState(false);
  const [overrides, setOverrides] = useState<Map<string, TaskOverride>>(
    new Map()
  );
  const [exitingIds, setExitingIds] = useState<Set<string>>(new Set());
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [baseTasks, setBaseTasks] = useState<Task[]>([]);

  // Recompute tasks when time or data changes
  useEffect(() => {
    const classified = classifyTasks({
      storeData,
      currentTs,
      existingTasks: baseTasks,
    });
    setBaseTasks(classifyTasks({
      storeData,
      currentTs,
      existingTasks: [],
    }));
  }, [currentTs, storeData]);

  const rawTasks = useMemo(() => {
    const classified = classifyTasks({
      storeData,
      currentTs,
      existingTasks: [],
    });
    return collapseFacingTasks(classified);
  }, [storeData, currentTs]);

  const tasks = useMemo(() => {
    return rawTasks.map((t) => {
      const key = taskKey(t.zoneId, t.skuCode);
      const override = overrides.get(key);
      if (override) {
        return { ...t, state: override.state };
      }
      return t;
    });
  }, [rawTasks, overrides]);

  const openTasks = useMemo(
    () => getOpenTasks(tasks, currentTs),
    [tasks, currentTs]
  );

  const totalAtRisk = useMemo(
    () => openTasks.reduce((s, t) => s + t.valueAtRiskPerHour, 0),
    [openTasks]
  );

  useEffect(() => {
    if (!isPlaying) return;
    const interval = setInterval(() => {
      setCurrentTs((prev) => {
        const next = prev + PLAY_SPEED * 1000;
        const dayEnd = getDayEndTs();
        if (next >= dayEnd) {
          setIsPlaying(false);
          return dayEnd;
        }
        return next;
      });
    }, 1000);
    return () => clearInterval(interval);
  }, [isPlaying]);

  const addToast = useCallback((text: string) => {
    const id = `toast-${Date.now()}`;
    setToasts((prev) => [...prev, { id, text }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  const play = useCallback(() => setIsPlaying(true), []);
  const pause = useCallback(() => setIsPlaying(false), []);

  const setTime = useCallback((ts: number) => {
    setCurrentTs(ts);
  }, []);

  const applyOverride = useCallback(
    (task: Task, state: Task["state"]) => {
      const key = taskKey(task.zoneId, task.skuCode);
      setExitingIds((prev) => new Set(prev).add(task.id));
      setTimeout(() => {
        setOverrides((prev) => {
          const next = new Map(prev);
          next.set(key, { state, resolvedTs: currentTs });
          return next;
        });
        setExitingIds((prev) => {
          const next = new Set(prev);
          next.delete(task.id);
          return next;
        });
      }, 300);
    },
    [currentTs]
  );

  const resolveRestocked = useCallback(
    (taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      if (task) applyOverride(task, "resolved_restocked");
    },
    [tasks, applyOverride]
  );

  const resolveNotFound = useCallback(
    (taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      if (!task) return;

      setStoreData((prev) => ({
        ...prev,
        inventory: prev.inventory.map((r) =>
          r.zoneId === task.zoneId && r.skuCode === task.skuCode
            ? { ...r, systemStock: 0 }
            : r
        ),
      }));

      applyOverride(task, "resolved_not_found");

      const value = task.valueAtRiskPerHour;
      addToast(
        `Stock set to 0. ₹${Math.round(value).toLocaleString("en-IN")}/hr at risk cleared. Store pickup will stop promising this item.`
      );
    },
    [tasks, applyOverride, addToast]
  );

  const dismissWrongCall = useCallback(
    (taskId: string) => {
      const task = tasks.find((t) => t.id === taskId);
      if (task) {
        applyOverride(task, "dismissed_wrong_call");
        addToast("Dismissed. This feedback trains the detector for next time.");
      }
    },
    [tasks, applyOverride, addToast]
  );

  const dismissToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const getTaskById = useCallback(
    (id: string) => tasks.find((t) => t.id === id),
    [tasks]
  );

  const value: SimulationContextValue = {
    currentTs,
    isPlaying,
    seed,
    storeData,
    tasks,
    openTasks,
    totalAtRisk,
    play,
    pause,
    setTime,
    resolveRestocked,
    resolveNotFound,
    dismissWrongCall,
    toasts,
    dismissToast,
    getTaskById,
  };

  return (
    <SimulationContext.Provider value={value}>
      {children}
    </SimulationContext.Provider>
  );
}

export function useSimulation() {
  const ctx = useContext(SimulationContext);
  if (!ctx)
    throw new Error("useSimulation must be used within SimulationProvider");
  return ctx;
}

