"use client";

import { useState } from "react";
import { ClockScrubber } from "@/components/ClockScrubber";
import { useSimulation } from "@/hooks/useSimulation";
import {
  getCameraZones,
  getUncoveredZones,
  getCameraStatusAtTs,
  getLastHeartbeat,
} from "@/lib/generator";
import { tsToClock } from "@/lib/time";

const CAMERA_IDS = [
  "cam-1",
  "cam-2",
  "cam-3",
  "cam-4",
  "cam-5",
  "cam-6",
  "cam-7",
  "cam-8",
];

function statusColor(status: string) {
  if (status === "ok") return "bg-green-500";
  if (status === "degraded") return "bg-amber-400";
  return "bg-neutral-300";
}

export default function HealthPage() {
  const { storeData, currentTs } = useSimulation();
  const [expandedCam, setExpandedCam] = useState<string | null>(null);

  const coveredZones = storeData.zones.filter((z) => z.covered);
  const uncovered = getUncoveredZones(storeData.zones);
  const coveragePct = Math.round(
    (coveredZones.length / storeData.zones.length) * 100
  );
  const uncoveredAisles = [...new Set(uncovered.map((z) => z.aisle))];

  const offlineCameras = CAMERA_IDS.filter(
    (id) =>
      getCameraStatusAtTs(storeData.heartbeats, id, currentTs) === "offline"
  );

  const lowConfZones = storeData.lowConfidenceZones
    .map((id) => storeData.zones.find((z) => z.id === id))
    .filter(Boolean);

  return (
    <div className="max-w-lg mx-auto">
      <ClockScrubber />

      <div className="px-4 py-4">
        <h1 className="text-lg font-medium mb-1">Store health</h1>
        <p className="text-sm text-neutral-500 mb-4">
          {coveragePct}% camera coverage
          {uncoveredAisles.length > 0 &&
            ` · ${uncoveredAisles.join(", ")} uncovered`}
        </p>

        <h2 className="text-sm font-medium text-neutral-500 mb-2">Cameras</h2>
        <div className="space-y-2">
          {CAMERA_IDS.map((camId) => {
            const status = getCameraStatusAtTs(
              storeData.heartbeats,
              camId,
              currentTs
            );
            const lastHb = getLastHeartbeat(
              storeData.heartbeats,
              camId,
              currentTs
            );
            const zones = getCameraZones(storeData.zones, camId);
            const isExpanded = expandedCam === camId;

            return (
              <div key={camId} className="border border-neutral-200 rounded">
                <button
                  onClick={() => setExpandedCam(isExpanded ? null : camId)}
                  className="w-full flex items-center gap-3 px-3 py-2.5 text-left"
                >
                  <span
                    className={`w-2.5 h-2.5 rounded-full shrink-0 ${statusColor(status)}`}
                  />
                  <span className="text-sm font-medium flex-1">
                    Camera {camId.replace("cam-", "")}
                  </span>
                  <span className="text-xs text-neutral-400 capitalize">
                    {status}
                  </span>
                  {lastHb && (
                    <span className="text-xs text-neutral-400 tabular-nums">
                      {tsToClock(lastHb.ts)}
                    </span>
                  )}
                </button>
                {isExpanded && (
                  <div className="px-3 pb-2 text-xs text-neutral-500">
                    Covers:{" "}
                    {zones.map((z) => `${z.aisle} ${z.section}`).join(", ")}
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div className="mt-6 bg-neutral-50 rounded-lg p-4">
          <h2 className="text-sm font-medium mb-3">
            What OnShelf cannot see today
          </h2>
          <ul className="text-sm text-neutral-600 space-y-2">
            {offlineCameras.length > 0 && (
              <li>
                <span className="text-neutral-900 font-medium">
                  Offline cameras:
                </span>{" "}
                {offlineCameras
                  .map((c) => `Camera ${c.replace("cam-", "")}`)
                  .join(", ")}
              </li>
            )}
            {uncoveredAisles.length > 0 && (
              <li>
                <span className="text-neutral-900 font-medium">
                  Uncovered aisles:
                </span>{" "}
                {uncoveredAisles.join(", ")}
              </li>
            )}
            {lowConfZones.length > 0 && (
              <li>
                <span className="text-neutral-900 font-medium">
                  Low-confidence zones:
                </span>{" "}
                {lowConfZones
                  .map((z) => `${z!.aisle} ${z!.section}`)
                  .join(", ")}
              </li>
            )}
            {offlineCameras.length === 0 &&
              uncoveredAisles.length === 0 &&
              lowConfZones.length === 0 && (
                <li>All systems nominal.</li>
              )}
          </ul>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useState, useMemo } from "react";
import { generateRegionalStores } from "@/lib/regional";
import type { RegionalStore } from "@/types";

type SortKey = "completionRate7d" | "rupeesAtRiskPerHour" | "openTasks";

function formatPct(n: number) {
  return `${Math.round(n * 100)}%`;
}

function formatRupee(n: number) {
  return `₹${n.toLocaleString("en-IN")}`;
}

export default function RegionalPage() {
  const stores = useMemo(() => generateRegionalStores(), []);
  const [sortKey, setSortKey] = useState<SortKey>("completionRate7d");
  const [ascending, setAscending] = useState(true);

  const sorted = useMemo(() => {
    return [...stores].sort((a, b) => {
      const diff = a[sortKey] - b[sortKey];
      return ascending ? diff : -diff;
    });
  }, [stores, sortKey, ascending]);

  function handleSort(key: SortKey) {
    if (sortKey === key) {
      setAscending(!ascending);
    } else {
      setSortKey(key);
      setAscending(key === "completionRate7d");
    }
  }

  function SortHeader({
    label,
    key,
    align = "left",
  }: {
    label: string;
    key: SortKey;
    align?: "left" | "right";
  }) {
    const active = sortKey === key;
    return (
      <th
        className={`px-4 py-3 text-xs font-medium text-neutral-500 cursor-pointer select-none ${
          align === "right" ? "text-right" : "text-left"
        } ${active ? "text-neutral-900" : ""}`}
        onClick={() => handleSort(key)}
      >
        {label}
        {active && (ascending ? " ↑" : " ↓")}
      </th>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      <div className="max-w-5xl mx-auto px-6 py-8">
        <h1 className="text-2xl font-medium mb-1">Regional overview</h1>
        <p className="text-neutral-500 mb-6">12 stores · Bangalore region</p>

        <div className="overflow-x-auto border border-neutral-200 rounded-lg">
          <table className="w-full text-sm">
            <thead className="bg-neutral-50 border-b border-neutral-200">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-medium text-neutral-500">
                  Store
                </th>
                <SortHeader label="Open tasks" key="openTasks" align="right" />
                <SortHeader
                  label="₹/hr at risk"
                  key="rupeesAtRiskPerHour"
                  align="right"
                />
                <SortHeader
                  label="7d completion"
                  key="completionRate7d"
                  align="right"
                />
                <th className="px-4 py-3 text-right text-xs font-medium text-neutral-500">
                  Phantom rate
                </th>
                <th className="px-4 py-3 text-right text-xs font-medium text-neutral-500">
                  Coverage
                </th>
              </tr>
            </thead>
            <tbody>
              {sorted.map((store) => (
                <StoreRow key={store.id} store={store} />
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

function StoreRow({ store }: { store: RegionalStore }) {
  const isLowAdoption = store.completionRate7d < 0.2;

  return (
    <tr
      className={`border-b border-neutral-100 ${
        isLowAdoption ? "bg-red-50/40" : ""
      }`}
    >
      <td className="px-4 py-3 font-medium">
        {store.name}
        {isLowAdoption && (
          <span className="ml-2 text-xs text-urgent font-normal">
            Low adoption
          </span>
        )}
      </td>
      <td className="px-4 py-3 text-right tabular-nums">{store.openTasks}</td>
      <td className="px-4 py-3 text-right tabular-nums font-medium">
        {formatRupee(store.rupeesAtRiskPerHour)}
      </td>
      <td
        className={`px-4 py-3 text-right tabular-nums ${
          isLowAdoption ? "text-urgent font-medium" : ""
        }`}
      >
        {formatPct(store.completionRate7d)}
      </td>
      <td className="px-4 py-3 text-right tabular-nums text-neutral-500">
        {formatPct(store.phantomRate)}
      </td>
      <td className="px-4 py-3 text-right tabular-nums text-neutral-500">
        {formatPct(store.cameraCoverage)}
      </td>
    </tr>
  );
}

