function analyzeBackgroundStats(seed: number) {
  const rng = createRng(seed);
  const dropRate = sampleDropRate(rng);
  const storeData = generateStoreData(seed);
  const totalSignals = storeData.signals.length;
  const scriptedZoneIds = new Set(getScriptedGaps().map((g) => g.zoneId));
  const backgroundEstimate = storeData.signals.filter(
    (s) => !scriptedZoneIds.has(s.zoneId) ||
      !getScriptedGaps().some(
        (g) => g.zoneId === s.zoneId && s.ts >= g.startTs && s.ts < g.endTs
      )
  ).length;
  return {
    dropRate,
    expected: backgroundEstimate + 50,
    dropped: Math.round(backgroundEstimate * dropRate),
    totalSignals,
  };
}

function verifyScriptedEvents(storeData: ReturnType<typeof generateStoreData>): string[] {
  const checks = [
    { label: "09:26 phantom ATT-003", ts: hourToTs(9, 26), zone: "A3-L2" },
    { label: "11:05 cam-4 degraded", ts: hourToTs(11, 5), zone: "A3-L2" },
    { label: "15:10 facing BEV-001", ts: hourToTs(15, 10), zone: "A5-L1" },
    { label: "17:45 peak RIC-001", ts: hourToTs(17, 45), zone: "A4-L1" },
  ];

  return checks.map(({ label, ts, zone }) => {
    const windowStart = ts - 20 * 60 * 1000;
    const recent = storeData.signals.filter(
      (s) => s.zoneId === zone && s.ts >= windowStart && s.ts <= ts
