"use client";

import { useState } from "react";
import Link from "next/link";
import type { Task } from "@/types";
import {
  getConfidenceLabel,
  getDisagreementSentence,
  getTaskAction,
  formatRupee,
} from "@/lib/classification";
import { getSku, getZone } from "@/lib/generator";
import { minutesOpen } from "@/lib/time";
import { useSimulation } from "@/hooks/useSimulation";
import { NotInBackroomSheet } from "./NotInBackroomSheet";

interface Props {
  task: Task;
  exiting?: boolean;
}

export function TaskRow({ task, exiting }: Props) {
  const { storeData, currentTs, resolveRestocked, dismissWrongCall } =
    useSimulation();
  const [showSheet, setShowSheet] = useState(false);

  const zone = getZone(storeData.zones, task.zoneId);
  const sku = getSku(storeData.zones, task.zoneId, task.skuCode);
  const label = getConfidenceLabel(task.confidence, task.mode);
  const isPhantom = task.kind === "phantom_suspected";
  const isPredicted = task.mode === "predicted" || label === "Predicted";
  const mins = minutesOpen(task.openedTs, currentTs);
  const statusLabel =
    task.mode === "predicted" ? "Predicted, camera offline" : label;

  const accent =
    isPhantom && !isPredicted
      ? "border-l-urgent"
      : isPredicted
        ? "border-l-predicted"
        : "border-l-transparent";

  return (
    <>
      <article
        className={`border-b border-neutral-200 border-l-[3px] ${accent} ${
          exiting
            ? "animate-row-exit motion-reduce:animate-none opacity-0"
            : ""
        }`}
      >
        <Link
          href={`/evidence?id=${encodeURIComponent(task.id)}&zone=${task.zoneId}&sku=${task.skuCode}`}
          className="block px-4 pt-3.5 pb-3"
        >
          <div className="flex items-baseline justify-between gap-4">
            <h2 className="text-xl font-medium leading-none">{zone?.aisle}</h2>
            <p className="text-xl font-medium tabular-nums leading-none shrink-0">
              {formatRupee(task.valueAtRiskPerHour)}
              <span className="text-[11px] font-normal text-neutral-400">
                /hr
              </span>
            </p>
          </div>

          <p className="text-[11px] text-neutral-400 mt-1">{zone?.section}</p>

          <p className="text-xs text-neutral-500 mt-2.5 leading-snug">
            {sku?.name ?? task.skuCode}. {getDisagreementSentence(task, storeData.zones)}
          </p>

          <p className="text-[11px] text-neutral-400 mt-2">
            {mins}m open
            <span className="mx-1.5">·</span>
            <span className={isPredicted ? "text-predicted" : "text-neutral-400"}>
              {statusLabel}
            </span>
            <span className="mx-1.5">·</span>
            <span
              className={
                isPhantom && !isPredicted
                  ? "text-urgent"
                  : "text-neutral-400"
              }
            >
              {getTaskAction(task.kind)}
            </span>
          </p>
        </Link>

        <div className="flex border-t border-neutral-100">
          <button
            onClick={() => resolveRestocked(task.id)}
            className="flex-1 py-3.5 text-sm font-medium border-r border-neutral-100 active:bg-neutral-50"
          >
            Restocked
          </button>
          <button
            onClick={() => setShowSheet(true)}
            className="flex-1 py-3.5 text-sm border-r border-neutral-100 active:bg-neutral-50"
          >
            Not in backroom
          </button>
          <button
            onClick={() => dismissWrongCall(task.id)}
            className="flex-1 py-3.5 text-sm text-neutral-400 active:bg-neutral-50"
          >
            Wrong call
          </button>
        </div>
      </article>

      {showSheet && (
        <NotInBackroomSheet task={task} onClose={() => setShowSheet(false)} />
      )}
    </>
  );
}

"use client";

import { ClockScrubber } from "@/components/ClockScrubber";
import { TaskRow } from "@/components/TaskRow";
import { UncoveredStrip } from "@/components/UncoveredStrip";
import { useSimulation } from "@/hooks/useSimulation";
import { formatRupee } from "@/lib/classification";
import { nextCheckTs, tsToClock } from "@/lib/time";

export default function GapsPage() {
  const { openTasks, totalAtRisk, currentTs, exitingIds } = useSimulation();
  const nextCheck = nextCheckTs(currentTs);

  return (
    <div className="max-w-lg mx-auto bg-white">
      <ClockScrubber />

      <p className="px-4 py-2.5 text-xs text-neutral-500 border-b border-neutral-200">
        {openTasks.length === 0 ? (
          <>Nothing open. Next check at {tsToClock(nextCheck)}.</>
        ) : (
          <>
            {openTasks.length} open ·{" "}
            <span className="tabular-nums">
              {formatRupee(totalAtRisk)}/hr at risk
            </span>
          </>
        )}
      </p>

      <UncoveredStrip />

      {openTasks.length > 0 && (
        <section aria-label="Open gaps">
          {openTasks.map((task) => (
            <TaskRow
              key={task.id}
              task={task}
              exiting={exitingIds.has(task.id)}
            />
          ))}
        </section>
      )}
    </div>
  );
}

"use client";

import { useSimulation } from "@/hooks/useSimulation";
import { tsToClock, getDayStartTs, getDayEndTs } from "@/lib/time";

export function ClockScrubber() {
  const { currentTs, isPlaying, play, pause, setTime, seed } = useSimulation();
  const dayStart = getDayStartTs();
  const dayEnd = getDayEndTs();

  return (
    <header className="sticky top-0 z-30 bg-white border-b border-neutral-200 px-4 py-2.5">
      <div className="flex items-baseline justify-between mb-2">
        <time className="text-xl font-medium tabular-nums">
          {tsToClock(currentTs)}
        </time>
        <div className="flex items-baseline gap-3 text-xs text-neutral-400">
          <span>seed {seed}</span>
          <button
            onClick={isPlaying ? pause : play}
            className="text-neutral-900 font-medium"
            aria-label={isPlaying ? "Pause" : "Play"}
          >
            {isPlaying ? "Pause" : "Play"}
          </button>
        </div>
      </div>
      <input
        type="range"
        min={dayStart}
        max={dayEnd}
        value={currentTs}
        onChange={(e) => setTime(Number(e.target.value))}
        className="w-full h-px appearance-none bg-neutral-300 cursor-pointer
          [&::-webkit-slider-thumb]:appearance-none
          [&::-webkit-slider-thumb]:w-3
          [&::-webkit-slider-thumb]:h-3
          [&::-webkit-slider-thumb]:bg-neutral-900
          [&::-moz-range-thumb]:w-3
          [&::-moz-range-thumb]:h-3
          [&::-moz-range-thumb]:border-0
          [&::-moz-range-thumb]:bg-neutral-900"
        aria-label="Time scrubber"
      />
      <div className="flex justify-between text-[10px] text-neutral-400 mt-1 tabular-nums">
        <span>06:00</span>
        <span>22:00</span>
      </div>
    </header>
  );
}

"use client";

import { useState } from "react";
import { useSimulation } from "@/hooks/useSimulation";
import { getUncoveredZones } from "@/lib/generator";

export function UncoveredStrip() {
  const { storeData } = useSimulation();
  const uncovered = getUncoveredZones(storeData.zones);
  const [expanded, setExpanded] = useState(false);

  if (uncovered.length === 0) return null;

  const aisles = [...new Set(uncovered.map((z) => z.aisle))];

  return (
    <div className="border-b border-neutral-200">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full px-4 py-2 text-left text-[11px] text-neutral-400"
      >
        No camera sees {aisles.join(", ")}
        <span className="ml-1">{expanded ? "▾" : "▸"}</span>
      </button>
      {expanded && (
        <div className="px-4 pb-2 text-[11px] text-neutral-400">
          {uncovered.map((z) => (
            <p key={z.id}>{z.aisle} · {z.section}</p>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useSimulation } from "@/hooks/useSimulation";

export function ToastContainer() {
  const { toasts, dismissToast } = useSimulation();

  if (toasts.length === 0) return null;

  return (
    <div className="fixed bottom-16 left-0 right-0 z-50 px-4 pointer-events-none">
      {toasts.map((toast) => (
        <div
          key={toast.id}
