  let offlineSince: number | null = null;
  for (const ev of script.events) {
    if (ev.ts > ts) break;
    if (ev.status === "offline") {
      if (offlineSince === null) offlineSince = ev.ts;
    } else {
      offlineSince = null;
    }
  }

  return getCameraStatusAt(cameraId, ts, script) === "offline"
    ? offlineSince
    : null;
}

